import { describe, expect, it, vi } from 'vitest';
import { Room } from '../src/domain-model/Room.js';
import { RoomController } from '../src/api-layer/RoomController.js';
import { AvailabilityService } from '../src/domain-services/AvailabilityService.js';
import { RoomRepository } from '../src/persistence/RoomRepository.js';
import { BookingRepository } from '../src/persistence/BookingRepository.js';

const START = '2030-01-01T10:00:00.000Z';
const END = '2030-01-01T11:00:00.000Z';

function makeRooms(): Room[] {
  return [
    new Room('r1', 'Alpha', 8, 1, ['projector', 'whiteboard'], true),
    new Room('r2', 'Beta', 4, 2, ['screen'], true),
  ];
}

function makeRoomRepo(rooms: Room[]) {
  const findAll = vi.fn(async () => rooms);
  const repo = { findAll, findById: vi.fn(), save: vi.fn(), delete: vi.fn() };
  return { repo: repo as unknown as RoomRepository, findAll };
}

function makeBookingRepo(busyRoomIds: string[]) {
  const findOverlapping = vi.fn(async (roomId: string) =>
    busyRoomIds.includes(roomId) ? [{ id: 'b1', roomId }] : [],
  );
  const repo = { findOverlapping, saveIfFree: vi.fn(), findById: vi.fn(), findByEmail: vi.fn(), findByRoomAndDay: vi.fn(), countFutureByRoom: vi.fn(), update: vi.fn() };
  return { repo: repo as unknown as BookingRepository, findOverlapping };
}

function makeService(rooms: Room[], busyRoomIds: string[]) {
  const roomRepo = makeRoomRepo(rooms);
  const bookingRepo = makeBookingRepo(busyRoomIds);
  const service = new AvailabilityService(roomRepo.repo, bookingRepo.repo);
  return { service, roomRepo, bookingRepo };
}

describe('UC-001 View room availability', () => {
  it("REQ-001 AC1: Given a date and time range, rooms with no booking overlapping that range are listed as free", async () => {
    const { service } = makeService(makeRooms(), ['r2']);
    const free = await service.findFreeRooms(new Date(START), new Date(END));
    expect(free.map((r) => r.id)).toContain('r1');
  });

  it("REQ-001 AC2: Rooms with an overlapping booking are not shown as free", async () => {
    const { service } = makeService(makeRooms(), ['r2']);
    const free = await service.findFreeRooms(new Date(START), new Date(END));
    expect(free.map((r) => r.id)).not.toContain('r2');
  });

  it("REQ-001 AC3: Each listed room shows name, capacity, floor and equipment", async () => {
    const { service } = makeService(makeRooms(), []);
    const free = await service.findFreeRooms(new Date(START), new Date(END));
    const alpha = free.find((r) => r.id === 'r1');
    expect(alpha).toBeDefined();
    expect(alpha?.name).toBe('Alpha');
    expect(alpha?.capacity).toBe(8);
    expect(alpha?.floor).toBe(1);
    expect(alpha?.equipment).toEqual(['projector', 'whiteboard']);
  });

  it("REQ-001 AC4: Deactivated rooms are not listed as bookable", async () => {
    const rooms = [
      new Room('r1', 'Alpha', 8, 1, [], true),
      new Room('r3', 'Gamma', 6, 3, [], false),
    ];
    const { service } = makeService(rooms, []);
    const free = await service.findFreeRooms(new Date(START), new Date(END));
    expect(free.map((r) => r.id)).not.toContain('r3');
  });

  it.todo("REQ-006 AC1: manual: browser usability requires a person to open the app in a web browser without installing client software");

  it("SEQ-001 scenario: View room availability", async () => {
    const { service, roomRepo, bookingRepo } = makeService(makeRooms(), ['r2']);
    const controller = new RoomController(service, null as any, null as any);
    const result = await controller.listAvailable(START, END);
    expect(roomRepo.findAll).toHaveBeenCalledTimes(1);
    expect(bookingRepo.findOverlapping).toHaveBeenCalled();
    expect(result.map((r) => r.id)).toEqual(['r1']);
  });
});

import { describe, expect, it } from 'vitest';
import request from 'supertest';
import { DatabaseSync } from 'node:sqlite';
import { createApp } from '../src/app/app.js';
import { Booking } from '../src/domain-model/Booking.js';
import { BookingRepository } from '../src/persistence/BookingRepository.js';

const FUTURE_START = new Date('2099-01-01T10:00:00.000Z');
const FUTURE_END = new Date('2099-01-01T11:00:00.000Z');
const PAST_START = new Date('2000-01-01T10:00:00.000Z');
const PAST_END = new Date('2000-01-01T11:00:00.000Z');
const OWNER = 'owner@example.com';

async function seedBooking(
  db: DatabaseSync,
  id: string,
  start: Date,
  end: Date,
  email: string,
  roomId = 'room-1',
): Promise<Booking> {
  const repo = new BookingRepository(db);
  return repo.saveIfFree(new Booking(id, roomId, start, end, 'Owner', email, false));
}

describe('UC-003 Cancel own booking', () => {
  it('REQ-004 AC1: A user can cancel a not-yet-started booking created with their email', async () => {
    const db = new DatabaseSync(':memory:');
    await seedBooking(db, 'b-1', FUTURE_START, FUTURE_END, OWNER);
    const app = createApp(db);
    const res = await request(app).delete('/api/bookings/b-1').send({ email: OWNER });
    expect(res.status).toBe(200);
    const stored = await new BookingRepository(db).findById('b-1');
    expect(stored?.cancelled).toBe(true);
  });

  it('REQ-004 AC2: After cancellation the time slot is shown as free', async () => {
    const db = new DatabaseSync(':memory:');
    await seedBooking(db, 'b-2', FUTURE_START, FUTURE_END, OWNER);
    const app = createApp(db);
    const res = await request(app).delete('/api/bookings/b-2').send({ email: OWNER });
    expect(res.status).toBe(200);
    const dayStart = new Date('2099-01-01T00:00:00.000Z');
    const dayEnd = new Date('2099-01-02T00:00:00.000Z');
    const onDay = await new BookingRepository(db).findByRoomAndDay('room-1', dayStart, dayEnd);
    const active = onDay.filter((b) => !b.cancelled);
    expect(active).toHaveLength(0);
  });

  it('REQ-004 AC3: A user cannot cancel a booking created with a different email', async () => {
    const db = new DatabaseSync(':memory:');
    await seedBooking(db, 'b-3', FUTURE_START, FUTURE_END, OWNER);
    const app = createApp(db);
    const res = await request(app).delete('/api/bookings/b-3').send({ email: 'other@example.com' });
    expect(res.status).toBeGreaterThanOrEqual(400);
    const stored = await new BookingRepository(db).findById('b-3');
    expect(stored?.cancelled).toBe(false);
  });

  it('REQ-004 AC4: Cancelling a booking that has already started or ended is rejected for a user', async () => {
    const db = new DatabaseSync(':memory:');
    await seedBooking(db, 'b-4', PAST_START, PAST_END, OWNER);
    const app = createApp(db);
    const res = await request(app).delete('/api/bookings/b-4').send({ email: OWNER });
    expect(res.status).toBeGreaterThanOrEqual(400);
    const stored = await new BookingRepository(db).findById('b-4');
    expect(stored?.cancelled).toBe(false);
  });

  it('SEQ-003 scenario: Cancel own booking', async () => {
    const db = new DatabaseSync(':memory:');
    await seedBooking(db, 'b-5', FUTURE_START, FUTURE_END, OWNER);
    const app = createApp(db);
    const res = await request(app).delete('/api/bookings/b-5').send({ email: OWNER });
    expect(res.status).toBe(200);
    const stored = await new BookingRepository(db).findById('b-5');
    expect(stored).not.toBeNull();
    expect(stored?.cancelled).toBe(true);
  });
});

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import request from 'supertest';
import { createApp } from '../src/app/app.js';
import { RoomController } from '../src/api-layer/RoomController.js';
import { BookingController } from '../src/api-layer/BookingController.js';
import { AdminController } from '../src/api-layer/AdminController.js';
import { AdminAuthService } from '../src/domain-services/AdminAuthService.js';
import { AdminGuard } from '../src/api-layer/AdminGuard.js';
import { AvailabilityService } from '../src/domain-services/AvailabilityService.js';
import { RoomService } from '../src/domain-services/RoomService.js';
import { BookingService } from '../src/domain-services/BookingService.js';

const ENV_NAME = 'ADMIN_PASSWORD';
const CORRECT = 'correct-horse-battery';
const WRONG = 'definitely-not-the-password';

let previous: string | undefined;

beforeEach(() => {
  previous = process.env[ENV_NAME];
  process.env[ENV_NAME] = CORRECT;
});

afterEach(() => {
  if (previous === undefined) {
    delete process.env[ENV_NAME];
  } else {
    process.env[ENV_NAME] = previous;
  }
});

function buildAuth(): AdminAuthService {
  return new AdminAuthService();
}

function buildRoomController(auth: AdminAuthService): RoomController {
  const guard = new AdminGuard(auth);
  return new RoomController(
    new AvailabilityService(),
    new RoomService(),
    guard,
  );
}

function buildBookingController(auth: AdminAuthService): BookingController {
  const guard = new AdminGuard(auth);
  return new BookingController(new BookingService(), guard);
}

describe('UC-005 Admin login', () => {
  it('REQ-009 AC1: Entering the correct password enables admin functions', async () => {
    const auth = buildAuth();
    const token = auth.verifyPassword(CORRECT);
    expect(token).not.toBeNull();
    expect(auth.isValidToken(token as string)).toBe(true);
    const guard = new AdminGuard(auth);
    expect(() => guard.requireAdmin(token as string)).not.toThrow();
  });

  it('REQ-009 AC2: Entering a wrong password does not enable admin functions', async () => {
    const auth = buildAuth();
    const token = auth.verifyPassword(WRONG);
    expect(token).toBeNull();
    const guard = new AdminGuard(auth);
    expect(() => guard.requireAdmin('')).toThrow();
  });

  it('REQ-009 AC3: Admin actions called without valid admin authentication are rejected by the server', async () => {
    const auth = buildAuth();
    const rooms = buildRoomController(auth);
    const bookings = buildBookingController(auth);
    await expect(rooms.listAllRooms('invalid-token')).rejects.toThrow();
    await expect(
      rooms.createRoom('invalid-token', {
        name: 'Room X',
        capacity: 4,
        active: true,
      } as never),
    ).rejects.toThrow();
    await expect(
      bookings.adminCancelBooking('invalid-token', 'some-booking-id'),
    ).rejects.toThrow();
  });

  it('REQ-009 AC4: The password is read from an environment variable and is not stored in the source code', async () => {
    const first = 'env-secret-first-value';
    process.env[ENV_NAME] = first;
    const authFirst = buildAuth();
    expect(authFirst.verifyPassword(first)).not.toBeNull();

    const second = 'env-secret-second-value';
    process.env[ENV_NAME] = second;
    const authSecond = buildAuth();
    expect(authSecond.verifyPassword(second)).not.toBeNull();
    expect(authSecond.verifyPassword(first)).toBeNull();
  });

  it('SEQ-005 scenario: Admin login', async () => {
    const auth = buildAuth();
    const controller = new AdminController(auth);
    const token = await controller.login(CORRECT);
    expect(typeof token).toBe('string');
    expect(token.length).toBeGreaterThan(0);
    expect(auth.isValidToken(token)).toBe(true);

    const app = createApp();
    const res = await request(app)
      .post('/api/admin/login')
      .send({ password: CORRECT });
    expect(res.status).toBe(200);
    expect(typeof res.body).toBe('object');
  });
});

import { describe, expect, it } from 'vitest';
import request from 'supertest';
import { DatabaseSync } from 'node:sqlite';
import { createApp } from '../src/app/app.js';
import { Booking } from '../src/domain-model/Booking.js';
import { BookingRepository } from '../src/persistence/BookingRepository.js';

const EMAIL = 'alice@example.com';
const OTHER_EMAIL = 'mallory@example.com';
const ROOM = 'room-A';

async function createOwnBooking(app: ReturnType<typeof createApp>, start: string, end: string, email = EMAIL) {
  const res = await request(app)
    .post('/api/bookings')
    .send({ roomId: ROOM, start, end, name: 'Alice', email });
  return res;
}

describe('UC-004 Change own booking time', () => {
  it('REQ-010 AC1: A user can change the time of their own not-yet-started booking to a free valid slot in the same room', async () => {
    const db = new DatabaseSync(':memory:');
    const app = createApp(db);
    const created = await createOwnBooking(app, '2030-01-07T10:00:00.000Z', '2030-01-07T11:00:00.000Z');
    expect(created.status).toBe(201);
    const id = created.body.id as string;

    const res = await request(app)
      .put(`/api/bookings/${id}`)
      .send({ email: EMAIL, start: '2030-01-07T13:00:00.000Z', end: '2030-01-07T14:00:00.000Z' });

    expect(res.status).toBe(200);
    expect(new Date(res.body.startTime).toISOString()).toBe('2030-01-07T13:00:00.000Z');
    expect(new Date(res.body.endTime).toISOString()).toBe('2030-01-07T14:00:00.000Z');
    expect(res.body.roomId).toBe(ROOM);
  });

  it('REQ-010 AC2: A change that violates the overlap rule or time slot rules is rejected and the original booking stays unchanged', async () => {
    const db = new DatabaseSync(':memory:');
    const app = createApp(db);
    const first = await createOwnBooking(app, '2030-02-04T10:00:00.000Z', '2030-02-04T11:00:00.000Z');
    const second = await createOwnBooking(app, '2030-02-04T12:00:00.000Z', '2030-02-04T13:00:00.000Z');
    expect(first.status).toBe(201);
    expect(second.status).toBe(201);
    const id = second.body.id as string;

    const res = await request(app)
      .put(`/api/bookings/${id}`)
      .send({ email: EMAIL, start: '2030-02-04T10:30:00.000Z', end: '2030-02-04T11:30:00.000Z' });
    expect(res.status).toBe(400);
    expect(res.body).toHaveProperty('error');

    const repo = new BookingRepository(db);
    const stored = await repo.findById(id);
    expect(stored).not.toBeNull();
    expect(stored?.startTime.toISOString()).toBe('2030-02-04T12:00:00.000Z');
    expect(stored?.endTime.toISOString()).toBe('2030-02-04T13:00:00.000Z');
  });

  it('REQ-010 AC3: A user cannot change a booking created with a different email', async () => {
    const db = new DatabaseSync(':memory:');
    const app = createApp(db);
    const created = await createOwnBooking(app, '2030-03-11T10:00:00.000Z', '2030-03-11T11:00:00.000Z', EMAIL);
    expect(created.status).toBe(201);
    const id = created.body.id as string;

    const res = await request(app)
      .put(`/api/bookings/${id}`)
      .send({ email: OTHER_EMAIL, start: '2030-03-11T13:00:00.000Z', end: '2030-03-11T14:00:00.000Z' });
    expect([400, 404]).toContain(res.status);

    const repo = new BookingRepository(db);
    const stored = await repo.findById(id);
    expect(stored?.startTime.toISOString()).toBe('2030-03-11T10:00:00.000Z');
  });

  it('REQ-010 AC4: Changing a booking that has already started or ended is rejected', async () => {
    const db = new DatabaseSync(':memory:');
    const app = createApp(db);
    const repo = new BookingRepository(db);
    const past = new Booking(
      'b-past',
      ROOM,
      new Date('2020-01-06T10:00:00.000Z'),
      new Date('2020-01-06T11:00:00.000Z'),
      'Alice',
      EMAIL,
      false,
    );
    await repo.saveIfFree(past);

    const res = await request(app)
      .put('/api/bookings/b-past')
      .send({ email: EMAIL, start: '2030-04-01T13:00:00.000Z', end: '2030-04-01T14:00:00.000Z' });
    expect(res.status).toBe(400);
    expect(res.body).toHaveProperty('error');
  });

  it('REQ-010 AC5: A change moving the start into the past is rejected', async () => {
    const db = new DatabaseSync(':memory:');
    const app = createApp(db);
    const created = await createOwnBooking(app, '2030-05-06T10:00:00.000Z', '2030-05-06T11:00:00.000Z');
    expect(created.status).toBe(201);
    const id = created.body.id as string;

    const res = await request(app)
      .put(`/api/bookings/${id}`)
      .send({ email: EMAIL, start: '2020-05-06T10:00:00.000Z', end: '2020-05-06T11:00:00.000Z' });
    expect(res.status).toBe(400);
    expect(res.body).toHaveProperty('error');
  });

  it('SEQ-004 scenario: Change own booking time', async () => {
    const db = new DatabaseSync(':memory:');
    const app = createApp(db);
    const created = await createOwnBooking(app, '2030-06-03T09:00:00.000Z', '2030-06-03T10:00:00.000Z');
    expect(created.status).toBe(201);
    const id = created.body.id as string;

    const changed = await request(app)
      .put(`/api/bookings/${id}`)
      .send({ email: EMAIL, start: '2030-06-03T15:00:00.000Z', end: '2030-06-03T16:00:00.000Z' });
    expect(changed.status).toBe(200);

    const listed = await request(app).get('/api/bookings').query({ email: EMAIL });
    expect(listed.status).toBe(200);
    const mine = (listed.body as Array<{ id: string; startTime: string }>).find((b) => b.id === id);
    expect(mine).toBeDefined();
    expect(new Date(mine!.startTime).toISOString()).toBe('2030-06-03T15:00:00.000Z');
  });
});

import { describe, expect, it } from 'vitest';
import { Room } from '../src/domain-model/Room.js';
import { RoomController } from '../src/api-layer/RoomController.js';
import { RoomService } from '../src/domain-services/RoomService.js';
import { RoomRepository } from '../src/persistence/RoomRepository.js';
import { BookingRepository } from '../src/persistence/BookingRepository.js';
import { AdminGuard } from '../src/api-layer/AdminGuard.js';

const ADMIN_TOKEN = 'admin-token';
const USER_TOKEN = 'user-token';

function makeGuard(): AdminGuard {
  return {
    requireAdmin(token: string): void {
      if (token !== ADMIN_TOKEN) {
        throw new Error('Unauthorized');
      }
    },
  } as unknown as AdminGuard;
}

function makeRoomRepo(): { rooms: Map<string, Room>; repo: RoomRepository } {
  const rooms = new Map<string, Room>();
  const repo = {
    findAll: async (): Promise<Room[]> => [...rooms.values()],
    findById: async (id: string): Promise<Room | null> => rooms.get(id) ?? null,
    save: async (room: Room): Promise<Room> => {
      rooms.set(room.id, room);
      return room;
    },
    delete: async (id: string): Promise<void> => {
      rooms.delete(id);
    },
  } as unknown as RoomRepository;
  return { rooms, repo };
}

function makeBookingRepo(futureCount: number): BookingRepository {
  return {
    countFutureByRoom: async (_roomId: string): Promise<number> => futureCount,
  } as unknown as BookingRepository;
}

function build(futureCount = 0): {
  controller: RoomController;
  rooms: Map<string, Room>;
} {
  const { rooms, repo } = makeRoomRepo();
  const service = new RoomService(repo, makeBookingRepo(futureCount));
  const controller = new RoomController(
    {} as never,
    service,
    makeGuard(),
  );
  return { controller, rooms };
}

function seedRoom(rooms: Map<string, Room>, id = 'room-1'): Room {
  const room = new Room(id, 'Alpha', 10, 2, ['projector'], true);
  rooms.set(id, room);
  return room;
}

describe('UC-006 Manage rooms', () => {
  it('REQ-005 AC1: An admin can add a room with name, capacity, floor and equipment list, and it becomes available for booking', async () => {
    const { controller } = build();
    const created = await controller.createRoom(ADMIN_TOKEN, {
      name: 'Beta',
      capacity: 6,
      floor: 3,
      equipment: ['whiteboard', 'screen'],
      active: true,
    } as Omit<Room, 'id'>);
    expect(created.name).toBe('Beta');
    expect(created.capacity).toBe(6);
    expect(created.floor).toBe(3);
    expect(created.equipment).toEqual(['whiteboard', 'screen']);
    const all = await controller.listAllRooms(ADMIN_TOKEN);
    expect(all.some((r) => r.id === created.id && r.active === true)).toBe(true);
  });

  it('REQ-005 AC2: An admin can edit a room\'s name, capacity, floor and equipment', async () => {
    const { controller, rooms } = build();
    const room = seedRoom(rooms);
    const updated = await controller.updateRoom(ADMIN_TOKEN, room.id, {
      name: 'Gamma',
      capacity: 12,
      floor: 4,
      equipment: ['projector', 'phone'],
    });
    expect(updated.name).toBe('Gamma');
    expect(updated.capacity).toBe(12);
    expect(updated.floor).toBe(4);
    expect(updated.equipment).toEqual(['projector', 'phone']);
  });

  it('REQ-005 AC3: An admin can delete a room that has no future bookings', async () => {
    const { controller, rooms } = build(0);
    const room = seedRoom(rooms);
    await controller.deleteRoom(ADMIN_TOKEN, room.id);
    expect(rooms.has(room.id)).toBe(false);
  });

  it('REQ-005 AC4: Deleting a room with one or more future bookings is rejected with an error message', async () => {
    const { controller, rooms } = build(2);
    const room = seedRoom(rooms);
    await expect(controller.deleteRoom(ADMIN_TOKEN, room.id)).rejects.toThrow(
      /.+/,
    );
    expect(rooms.has(room.id)).toBe(true);
  });

  it('REQ-005 AC5: Non-admin users cannot perform these actions', async () => {
    const { controller, rooms } = build(0);
    const room = seedRoom(rooms);
    await expect(
      controller.createRoom(USER_TOKEN, {
        name: 'Delta',
        capacity: 4,
        floor: 1,
        equipment: [],
        active: true,
      } as Omit<Room, 'id'>),
    ).rejects.toThrow();
    await expect(
      controller.updateRoom(USER_TOKEN, room.id, { name: 'Hacked' }),
    ).rejects.toThrow();
    await expect(controller.deleteRoom(USER_TOKEN, room.id)).rejects.toThrow();
    expect(rooms.has(room.id)).toBe(true);
    expect(rooms.get(room.id)?.name).toBe('Alpha');
  });

  it('SEQ-006 scenario: Manage rooms', async () => {
    // deleteRoom: RoomController -> AdminGuard -> RoomService -> BookingRepository -> RoomRepository
    const { controller, rooms } = build(0);
    const room = seedRoom(rooms);
    await expect(controller.deleteRoom(USER_TOKEN, room.id)).rejects.toThrow();
    expect(rooms.has(room.id)).toBe(true);
    await controller.deleteRoom(ADMIN_TOKEN, room.id);
    expect(rooms.has(room.id)).toBe(false);
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { Booking } from '../src/domain-model/Booking.js';
import { BookingController } from '../src/api-layer/BookingController.js';
import { BookingService } from '../src/domain-services/BookingService.js';
import { TimeSlotPolicy } from '../src/domain-services/TimeSlotPolicy.js';

// Fixed "now": Monday 2030-01-07 09:00 Europe/Zurich (January, UTC+1).
const NOW = new Date('2030-01-07T08:00:00Z');

function zurich(local: string): Date {
  return new Date(`${local}+01:00`);
}

class FakeRoomRepository {
  private rooms: Record<string, { id: string; active: boolean }> = {
    'room-1': { id: 'room-1', active: true },
    'room-2': { id: 'room-2', active: true },
    'room-off': { id: 'room-off', active: false },
  };

  async findAll(): Promise<any[]> {
    return Object.values(this.rooms);
  }

  async findById(id: string): Promise<any | null> {
    return this.rooms[id] ?? null;
  }

  async save(room: any): Promise<any> {
    this.rooms[room.id] = room;
    return room;
  }

  async delete(id: string): Promise<void> {
    delete this.rooms[id];
  }
}

class FakeBookingRepository {
  items: Booking[] = [];

  private overlaps(b: Booking, roomId: string, start: Date, end: Date, excludeId: string | null): boolean {
    return !b.cancelled && b.roomId === roomId && b.id !== excludeId && b.startTime < end && b.endTime > start;
  }

  async findOverlapping(roomId: string, start: Date, end: Date, excludeId: string | null): Promise<Booking[]> {
    return this.items.filter((b) => this.overlaps(b, roomId, start, end, excludeId));
  }

  async saveIfFree(booking: Booking): Promise<Booking> {
    const clash = this.items.some((b) => this.overlaps(b, booking.roomId, booking.startTime, booking.endTime, null));
    if (clash) {
      throw new Error('Time slot overlaps an existing booking');
    }
    this.items.push(booking);
    return booking;
  }

  async findById(id: string): Promise<Booking | null> {
    return this.items.find((b) => b.id === id) ?? null;
  }

  async findByEmail(email: string): Promise<Booking[]> {
    return this.items.filter((b) => b.creatorEmail === email);
  }

  async findByRoomAndDay(roomId: string, dayStart: Date, dayEnd: Date): Promise<Booking[]> {
    return this.items.filter(
      (b) => b.roomId === roomId && !b.cancelled && b.startTime >= dayStart && b.startTime < dayEnd,
    );
  }

  async countFutureByRoom(roomId: string): Promise<number> {
    return this.items.filter((b) => b.roomId === roomId && !b.cancelled && b.startTime > NOW).length;
  }

  async update(booking: Booking): Promise<Booking> {
    this.items = this.items.map((b) => (b.id === booking.id ? booking : b));
    return booking;
  }
}

function setup() {
  const bookingRepo = new FakeBookingRepository();
  const roomRepo = new FakeRoomRepository();
  const service = new BookingService(new TimeSlotPolicy(), roomRepo as any, bookingRepo as any);
  const controller = new BookingController(service, {} as any);
  return { service, controller, bookingRepo, roomRepo };
}

