import request from 'supertest';
import { DatabaseSync } from 'node:sqlite';
import { createApp } from '../src/app/app.js';
import { Booking } from '../src/domain-model/Booking.js';
import { BookingRepository } from '../src/persistence/BookingRepository.js';

const FUTURE_START = new Date('2099-01-01T10:00:00.000Z');
const FUTURE_END = new Date('2099-01-01T11:00:00.000Z');
const PAST_START = new Date('2000-01-01T10:00:00.000Z');
const PAST_END = new Date('2000-01-01T11:00:00.000Z');
const OWNER = 'owner@example.com';

async function seedBooking(
  db: DatabaseSync,
  id: string,
  start: Date,
  end: Date,
  email: string,
  roomId = 'room-1',
): Promise<Booking> {
  const repo = new BookingRepository(db);
  return repo.saveIfFree(new Booking(id, roomId, start, end, 'Owner', email, false));
}

describe('UC-003 Cancel own booking', () => {
  it('REQ-004 AC1: A user can cancel a not-yet-started booking created with their email', async () => {
    const db = new DatabaseSync(':memory:');
    await seedBooking(db, 'b-1', FUTURE_START, FUTURE_END, OWNER);
    const app = createApp(db);
    const res = await request(app).delete('/api/bookings/b-1').send({ email: OWNER });
    expect(res.status).toBe(200);
    const stored = await new BookingRepository(db).findById('b-1');
    expect(stored?.cancelled).toBe(true);
  });

  it('REQ-004 AC2: After cancellation the time slot is shown as free', async () => {
    const db = new DatabaseSync(':memory:');
    await seedBooking(db, 'b-2', FUTURE_START, FUTURE_END, OWNER);
    const app = createApp(db);
    const res = await request(app).delete('/api/bookings/b-2').send({ email: OWNER });
    expect(res.status).toBe(200);
    const dayStart = new Date('2099-01-01T00:00:00.000Z');
    const dayEnd = new Date('2099-01-02T00:00:00.000Z');
    const onDay = await new BookingRepository(db).findByRoomAndDay('room-1', dayStart, dayEnd);
    const active = onDay.filter((b) => !b.cancelled);
    expect(active).toHaveLength(0);
  });

  it('REQ-004 AC3: A user cannot cancel a booking created with a different email', async () => {
    const db = new DatabaseSync(':memory:');
    await seedBooking(db, 'b-3', FUTURE_START, FUTURE_END, OWNER);
    const app = createApp(db);
    const res = await request(app).delete('/api/bookings/b-3').send({ email: 'other@example.com' });
    expect(res.status).toBeGreaterThanOrEqual(400);
    const stored = await new BookingRepository(db).findById('b-3');
    expect(stored?.cancelled).toBe(false);
  });

  it('REQ-004 AC4: Cancelling a booking that has already started or ended is rejected for a user', async () => {
    const db = new DatabaseSync(':memory:');
    await seedBooking(db, 'b-4', PAST_START, PAST_END, OWNER);
    const app = createApp(db);
    const res = await request(app).delete('/api/bookings/b-4').send({ email: OWNER });
    expect(res.status).toBeGreaterThanOrEqual(400);
    const stored = await new BookingRepository(db).findById('b-4');
    expect(stored?.cancelled).toBe(false);
  });

  it('SEQ-003 scenario: Cancel own booking', async () => {
    const db = new DatabaseSync(':memory:');
